pells":[],"inventory":[],"currencies":{"gold":5,"silver":10,"copper":0},"rations":5,"lanternOil":4,"customResources":[],"restLog":[],"revision":1,"updatedAt":"2026-10-28T07:01:13.177Z"}', 1, 0);
INSERT INTO campaigns (id, name, description, tone, status, owner_id, source_pack_id, settings, wizard_state, created_at, updated_at) VALUES ('zorvania-c1', 'زروانیا: کمپین نخست', 'ماجراجویی آغازین در سرزمین‌های ازهم‌گسیخته‌ی زمان، رازهای باستانی فره و رویارویی با گسسته‌زمان.', 'حماسی و اساطیری با تمرکز بر رازهای باستانی زمان و فره', 'active', 'user-dm', 'pack-zorvania', '{"units":"feet","startingLevel":1,"maxEntryLevel":20,"abilityScoreMethods":["standard_array","point_buy","roll","manual"],"approval":{"onCreate":false,"onLevelUp":false},"backstoryVisibility":"party","diceVisibility":"table","allowPlayerRollPrivate":true,"allowPlayerCreateCharacter":true,"encounterDefaults":{"showExactHp":false,"showAc":false,"showConditions":true,"showDefeated":true,"playerInitiativeRolls":true},"houseRules":"در جهان زروانیا، استراحت کوتاه ۱ ساعت و استراحت طولانی ۸ ساعت است. آسیب‌های زمانی نیازمند پالایش خاطره هستند."}', 'null', 1790578873177, 1793170773177);
INSERT INTO campaigns (id, name, description, tone, status, owner_id, source_pack_id, settings, wizard_state, created_at, updated_at) VALUES ('campaign-srd-test', 'سیاه‌چال کهن (کمپین آزمایشی ۵e)', 'یک کمپین آزمایشی مبتنی بر هسته مکانیکی D&D 5e بدون لور اختصاصی زروانیا.', 'ماجراجویی کلاسیک سیاهچال و کاوش گنج', 'active', 'user-dm', 'pack-srd-5e', '{"units":"feet","startingLevel":1,"maxEntryLevel":10,"abilityScoreMethods":["standard_array","point_buy","roll","manual"],"approval":{"onCreate":true,"onLevelUp":true},"backstoryVisibility":"party","diceVisibility":"table","allowPlayerRollPrivate":true,"allowPlayerCreateCharacter":true,"encounterDefaults":{"showExactHp":false,"showAc":false,"showConditions":true,"showDefeated":true,"playerInitiativeRolls":true},"houseRules":"قوانین استاندارد SRD 5e."}', 'null', 1791874873177, 1793084473177);
